<?php declare(strict_types=1);use App\Helpers\View;$e=static fn($x)=>htmlspecialchars((string)$x,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');ob_start();?><div class="btp-shell btp-workspace"><nav class="btp-breadcrumb"><a href="<?= $e(View::url('btp/dashboard')) ?>">BTP</a><span>/</span><strong>Bons de commande</strong></nav><header class="btp-banner"><small>COMMANDES CLIENTS</small><h1><i class="fa-solid fa-file-contract"></i> Liste des bons de commande</h1><p>Pièces clients et lignes reprises du devis, conservées par version.</p></header><p><a class="btp-primary-link" href="<?= $e(View::url('btp/bons-commande/nouveau')) ?>"><i class="fa-solid fa-plus"></i> Nouveau bon de commande</a></p><section class="btp-panel btp-section"><label>Rechercher un BC <input type="search" id="bc-search" placeholder="Référence, projet, client"></label></section><div class="btp-chantier-card-grid" id="bc-cards"><?php foreach($ordersBtp as $bc): ?><article class="btp-chantier-card" data-bc-card data-search="<?= $e(mb_strtolower($bc['reference'].' '.$bc['project_reference'].' '.$bc['intitule'].' '.$bc['client_nom'])) ?>"><div class="btp-chantier-card-head"><strong><?= $e($bc['reference']) ?></strong><span class="btp-chantier-status"><?= $e($bc['status']) ?></span></div><h3><?= $e($bc['intitule']) ?></h3><p>Client : <?= $e($bc['client_nom']) ?></p><p>Devis : <?= $e($bc['offer_title']) ?> · Révision <?= (int)$bc['revision'] ?></p><p>Réception : <?= $e($bc['received_at']) ?></p><p><strong><?= number_format((float)$bc['amount_ht'],2,',',' ') ?> FCFA HT</strong></p><div class="btp-chantier-card-actions"><a href="<?= $e(View::url('btp/projets/'.(int)$bc['projet_id'].'/documents/'.(int)$bc['document_id'])) ?>"><i class="fa-solid fa-download"></i> Télécharger le BC</a><a href="<?= $e(View::url('btp/projets/'.(int)$bc['projet_id'])) ?>">Voir le projet</a></div></article><?php endforeach; ?></div><?php if(!$ordersBtp): ?><section class="btp-panel"><p>Aucun bon de commande enregistré.</p></section><?php endif; ?></div><script>document.getElementById('bc-search').addEventListener('input',function(){const q=this.value.toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');document.querySelectorAll('[data-bc-card]').forEach(c=>c.hidden=!c.dataset.search.normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q))})</script><?php $content=ob_get_clean();require BASE_PATH.'/views/layouts/module.php';